with exploded as (select id, service, log_ts, latency_ms, status_code, k, attr_value from app_logs lateral view explode(context) t as k, attr_value), with_gaps as (select *, case when lag(log_ts) over (partition by k order by log_ts, id, k) is null or log_ts > lag(log_ts) over (partition by k order by log_ts, id, k) + interval 15 minutes then 1 else 0 end as new_group_flag from exploded), sessionized as (select *, sum(new_group_flag) over (partition by k order by log_ts, id, k rows between unbounded preceding and current row) as session_id from with_gaps), scored as (select *, sum(status_code) over (partition by k order by log_ts, id, k rows between unbounded preceding and current row) as cumulative_status_code, round(status_code / sum(status_code) over (partition by service), 4) as status_code_share, row_number() over (partition by service order by log_ts desc, id, k) as event_seq from sessionized), gaps as (select *, case when log_ts - lag(log_ts) over (partition by service order by log_ts, id, k) > interval 1 hour then 1 else 0 end as is_new_session from scored), islands as (select id, service, log_ts, latency_ms, k, new_group_flag, session_id, cumulative_status_code, sum(is_new_session) over (partition by service order by log_ts, id, k rows between unbounded preceding and current row) as session_no from gaps) select case when cumulative_status_code >= 1608 then 'HIGH' else 'LOW' end as cumulative_status_code_tier, date_trunc('hour', log_ts) as hour_window, case when session_no >= 8 then 'HIGH' else 'LOW' end as session_no_tier, approx_percentile(session_no, 0.5) as session_no_p50, sum(case when k = 'version' then cumulative_status_code else 0 end) as version_cumulative_status_code, round(sum(new_group_flag) / nullif(count(case when k = 'version' then 1 end), 0), 2) as new_group_flag_per_version, round(sum(session_id) / nullif(count(case when k = 'trace' then 1 end), 0), 2) as session_id_per_trace, sum(session_id) filter (where service = 'auth') as auth_total_session_id, approx_percentile(session_id, 0.5) as session_id_p50 from islands group by cube (case when cumulative_status_code >= 1608 then 'HIGH' else 'LOW' end, date_trunc('hour', log_ts), case when session_no >= 8 then 'HIGH' else 'LOW' end) order by session_id_per_trace desc nulls last
